      "typeVersion": 1,
      "position": [450, 300],
      "credentials": {
        "discordApi": {
          "id": "your-credentials-id"
        }
      }
    },
    {
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "={{$json[\"success\"]}}",
              "value2": true
            }
          ]
        }
      },
