        "functionCode": "return items.map(item => { /* 데이터 정제 로직 */ return item; });"
      },
      "name": "Code - Data Cleaning",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [500, 300]
    },
    {
      "parameters": {
        "functionCode": "const uniqueItems = []; const seen = new Set(); items.forEach(item => { const key = item.json.uniqueField; if (!seen.has(key)) { seen.add(key); uniqueItems.push(item); } }); return uniqueItems;"
      },
      "name": "Code - Remove Duplicates",
      "type": "n8n-nodes-base.code",
      "typeVersion": 1,
      "position": [700, 300]
    },
    {
      "parameters": {
        "operation": "appendOrUpdate",
        "sheetId": "your-sheet-id",
        "range": "Sheet1!A1:Z1000",
        "key": "uniqueField"
      },
      "name": "Google Sheets - Save Data",
      "type": "n8n-nodes-base.googleSheets",
      "typeVersion": 1,
      "position": [900, 300]
    }
  ],
  "connections": {
    "Local File Trigger": {
      "main": [
        [
          {
            "node": "Google Sheets - Get Data",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Google Sheets - Get Data": {
      "main": [
        [
          {
            "node": "Code - Data Cleaning",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Code - Data Cleaning": {
      "main": [
        [
          {
            "node": "Code - Remove Duplicates",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Code - Remove Duplicates": {
      "main": [
        [
          {
            "node": "Google Sheets - Save Data",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1"
  }
