        "options": {}
      },
      "name": "HTTP Request 2",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 1,
      "position": [250, 500]
    },
    {
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "={{ $json[\"error\"] }}",
              "value2": "true"
            }
          ]
        }
      },
      "name": "If",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [500, 300]
    },
    {
      "parameters": {
        "functionCode": "return items.map(item => {\n  delete item.json.error;\n  return item;\n});"
      },
      "name": "Data Cleanup",
      "type": "n8n-nodes-base.function",
      "typeVersion": 1,
      "position": [750, 300]
    },
    {
      "parameters": {
        "mode": "mergeByIndex"
      },
      "name": "Merge Data",
