      "typeVersion": 1,
      "position": [1000, 400]
    }
  ],
  "connections": {
    "HTTP Request 1": {
      "main": [
        [
          {
            "node": "If",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "HTTP Request 2": {
      "main": [
        [
          {
            "node": "Merge Data",
            "type": "main",
            "index": 1
          }
        ]
      ]
    },
    "If": {
      "main": [
        [
          {
            "node": "Data Cleanup",
            "type": "main",
            "index": 0
          }
        ],
        [
          {
            "node": "Merge Data",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "Data Cleanup": {
      "main": [
        [
          {
            "node": "Merge Data",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}
```

이 워크플로우는 첫 번째 데이터 소스에서 데이터를 가져온 후 에러를 확인하고, 에러가 있을 경우 데이터를 정제한 후 두 번째 소스의 데이터와 병합합니다. 두 소스에서 데이터를 성공적으로 가져오면 합쳐서 사용할 수 있습니다. 워크플로우를 실행하기 전에 각 노드의 설정을 사용하고자 하는 API와 데이터 구조에 맞게 수정해야 할 수 있습니다.

tier23.text:
**요청 분석 중...**

**목표:** 에러 발생 시 데이터를 정제하고 여러 소스의 데이터를 병합한다
**트리거:** `webhook` — 에러가 발생할 때 웹훅을 통해 워크플로우가 실행된다
**처리 단계:**
  1. **에러 데이터 수집** — 발생한 에러 데이터를 수집한다 (`HTTP Request`)
  2. **데이터 정제** — 수집된 에러 데이터를 정제한다 (`Code`)
  3. **외부 소스 데이터 수집** — 여러 외부 소스에서 추가 데이터를 수집한다 (`HTTP Request`)
  4. **데이터 병합** — 정제된 데이터와 외부 소스 데이터를 병합한다 (`Merge`)
**출력:** DB 저장 → 병합된 데이터를 데이터베이스에 저장한다
**복잡도:** 복잡

---

## 워크플로우 개요

이 워크플로우는 에러 발생 시 자동으로 실행되어 데이터를 수집하고 정제한 후, 여러 외부 소스에서 추가 데이터를 수집하여 최종적으로 병합하는 프로세스를 자동화합니다. 웹훅을 통해 에러 데이터를 수신하고, 이를 정제하여 유의미한 정보로 변환합니다. 이후, HTTP 요청을 통해 외부 소스에서 추가 데이터를 수집하고, 정제된 데이터와 병합하여 데이터베이스에 저장합니다. 이 워크플로우는 데이터의 일관성을 유지하고, 에러 발생 시 신속한 대응을 가능하게 하여 비즈니스 운영의 효율성을 높입니다.

## 전체 실행 흐름

1. **에러 데이터 수집**: 웹훅을 통해 에러 발생 시 데이터를 수신합니다.
2. **데이터 정제**: 수집된 에러 데이터를 `Code` 노드를 사용하여 정제합니다.
3. **외부 소스 데이터 수집**: `HTTP Request` 노드를 통해 여러 외부 소스에서 추가 데이터를 수집합니다.
4. **데이터 병합**: `Merge` 노드를 사용하여 정제된 데이터와 외부 소스 데이터를 병합합니다.
5. **데이터 저장**: 병합된 데이터를 데이터베이스에 저장합니다.

## 노드 구성

| 순서 | 노드명 | 타입 | 역할 | 주요 파라미터 |
|------|--------|------|------|--------------|
| 1 | Webhook | `n8n-nodes-base.webhook` | 에러 데이터 수집 | method: POST |
| 2 | Code | `n8n-nodes-base.code` | 데이터 정제 | code: JavaScript 코드 |
| 3 | HTTP Request | `n8n-nodes-base.httprequest` | 외부 소스 데이터 수집 | method: GET, url: 외부 API URL |
| 4 | Merge | `n8n-nodes-base.merge` | 데이터 병합 | mode: Merge By Key |
| 5 | Azure Cosmos DB | `n8n-nodes-base.azurecosmosdb` | 데이터 저장 | operation: Create Item |

