              "operation": "isTrue"
            }
          ]
        }
      },
      "name": "If",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [450, 300]
    },
    {
      "parameters": {
        "resource": "page",
        "operation": "create",
        "databaseId": "YOUR_NOTION_DATABASE_ID",
        "properties": {
          "Title": {
            "title": [
              {
                "text": {
                  "content": "Error Notification"
                }
              }
            ]
          },
          "Error Details": {
            "rich_text": [
              {
                "text": {
                  "content": "={{$json[\"error\"]}}"
                }
              }
            ]
          }
        }
      },
      "name": "Notion",
      "type": "n8n-nodes-base.notion",
      "typeVersion": 1,
