            "node": "If",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "If": {
      "main": [
        [
          {
            "node": "Notion",
            "type": "main",
            "index": 0
          }
        ],
        []
      ]
    }
  },
  "settings": {
    "executionOrder": "v1"
  }
}
```

## 주요 설정 가이드

### Webhook 설정
- **httpMethod**: `POST`로 설정하여 회원가입 데이터를 수신합니다.
- **path**: `user-signup`으로 설정하여 고유한 엔드포인트를 만듭니다.

### If 설정
- **조건**: `{{$json["error"] !== undefined}}`로 설정하여 에러 필드가 존재하는지 확인합니다.

### Notion 설정
- **Database ID**: Notion에서 에러 정보를 저장할 데이터베이스의 ID를 입력합니다.
- **Title**: "Error Notification"으로 설정하여 페이지 제목을 지정합니다.
- **Error Details**: `{{$json["error"]}}`로 설정하여 에러 세부 정보를 기록합니다.

## 운영 고려사항 및 개선 포인트

1. **에러 처리**: Webhook 수신 시 데이터 형식이 예상과 다를 경우를 대비하여 에러 핸들링 로직을 추가할 수 있습니다.
2. **성능 최적화**: 대량의 회원가입 요청을 처리할 때 Webhook 노드의 성능을 모니터링하고 필요 시 확장합니다.
3. **보안**: Webhook URL을 외부에 노출하지 않도록 주의하고, Notion API 키를 안전하게 관리합니다.
4. **확장 방향**: 에러 발생 시 이메일이나 Slack을 통해 추가 알림을 보내는 기능을 구현할 수 있습니다.

tier1.text:
n8n을 사용하여 이메일이 도착했을 때 여러 외부 서비스를 호출하고 Slack 채널로 알림을 보내는 워크플로우를 설정할 수 있습니다. 아래는 이를 위한 일반적인 워크플로우 예제입니다.

1. **이메일 수신 트리거**: 이메일을 수신했을 때 워크플로우를 시작할 수 있도록 이메일 트리거를 설정합니다.
2. **외부 서비스 호출**: HTTP 요청 노드를 사용하여 외부 서비스를 순차적으로 호출합니다.
3. **Slack 알림 발송**: Slack 노드를 사용하여 특정 채널로 메시지를 보냅니다.

아래는 이 워크플로우의 JSON 예시입니다.

```json
{
  "nodes": [
    {
      "parameters": {
        "event": "newEmail",
        "email": "your-email@example.com",
        "imap": {
          "host": "imap.example.com",
          "port": 993,
          "secure": true,
          "user": "your-email@example.com",
          "password": "your-email-password"
        }
      },
      "name": "Email Trigger",
      "type": "n8n-nodes-base.emailReadImap",
      "typeVersion": 1,
      "position": [200, 300]
    },
    {
      "parameters": {
        "url": "https://api.external-service1.com/endpoint",
        "options": {},
        "method": "GET"
      },
      "name": "HTTP Request 1",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 1,
      "position": [600, 300]
    },
    {
      "parameters": {
        "url": "https://api.external-service2.com/endpoint",
        "options": {},
        "method": "GET"
      },
      "name": "HTTP Request 2",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 1,
      "position": [1000, 300]
    },
    {
      "parameters": {
        "channel": "#your-slack-channel",
        "text": "새 이메일이 도착했습니다. 외부 서비스 호출이 완료되었습니다.",
        "attachments": []
      },
      "name": "Slack Notify",
      "type": "n8n-nodes-base.slack",
      "typeVersion": 1,
      "position": [1400, 300]
    }
  ],
  "connections": {
    "Email Trigger": {
      "main": [
        [
          {
            "node": "HTTP Request 1",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "HTTP Request 1": {
      "main": [
        [
          {
            "node": "HTTP Request 2",
            "type": "main",
            "index": 0
          }
        ]
      ]
    },
    "HTTP Request 2": {
      "main": [
        [
          {
            "node": "Slack Notify",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  }
}
```

이 워크플로우는 다음과 같이 동작합니다:
- `Email Trigger` 노드는 이메일 수신을 감지합니다.
- `HTTP Request 1`과 `HTTP Request 2` 노드는 순차적으로 외부 서비스를 호출합니다.
- 외부 서비스 호출이 완료되면 `Slack Notify` 노드가 Slack 채널로 알림을 보냅니다.

각 노드의 설정을 실제 환경에 맞게 조정해야 합니다. 예를 들어, 이메일 계정 정보, 외부 서비스 API 엔드포인트, Slack 채널 이름 등을 설정합니다.

