            "index": 0
          }
        ]
      ]
    },
    "외부 API 호출": {
      "main": [
        [
          {
            "node": "API 응답 처리",
            "type": "main",
            "index": 0
          }
        ]
      ]
    }
  },
  "settings": {
    "executionOrder": "v1"
  }
